// Logo component map
const logoComponents: Record<LogoType, React.FC<{ size?: number; filled?: boolean }>> = {
  claude: ClaudeIcon,
  airbnb: AirbnbIcon,
  apple: AppleIcon,
  discord: DiscordIcon,
  framer: FramerIcon,
  gemini: GeminiIcon,
  linear: LinearIcon,
  loom: LoomIcon,
  openai: OpenaiIcon,
  replit: ReplitIcon,
  twilio: TwilioIcon,
  copilot: CopilotIcon,
  google: GoogleIcon,
}

function Logo({ logo, variant = "default", size = 24, className }: LogoProps) {
  const LogoIcon = logoComponents[logo]
  const isFilled = variant === "filled"

  return (
    <span
      data-slot="logo"
      data-logo={logo}
      data-variant={variant}
      className={cn(
        "inline-flex shrink-0 items-center justify-center overflow-hidden",
        "text-content-strong",
        isFilled && "rounded-[var(--radius-8)]",
        className
      )}
      style={{ width: size, height: size }}
      role="img"
      aria-label={logoNames[logo]}
    >
      <LogoIcon size={size} filled={isFilled} />
    </span>
  )
}

export { Logo, logos, logoColors, logoNames }
export type { LogoType, LogoProps }
